#[derive(Debug, Clone)]
enum DateTime64 {
    Nat,
    Valid(i64),
}

fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    // Pre-allocate the result vector with the same length as the input
    let mut result = Vec::with_capacity(x.len());

    // For each element, push `true` if it's `Nat`, otherwise push `false`.
    for dt in x {
        match dt {
            DateTime64::Nat       => result.push(true),
            DateTime64::Valid(_)  => result.push(false),
        }
    }

    result
}

